feed:
	{% if section.title %}{{ section.title }}{% else %}{{ config.title }}{% endif %}
	{%- if section.description %}
	{{ section.description }}
    {%- elif config.description %}
	{{ config.description }}
	{%- endif %}


	{{ last_updated | date(format="%+") }}
	{{ feed_url | safe }}
	{%- for page in pages %}

		{{ page.title }}
		{{ page.date | date(format="%+") }}
		{{ page.updated | default(value=page.date) | date(format="%+") }}
        {%- if page.summary %}
        {{ page.summary }}
        {%- endif %}

		{%- if page.extra.link_url %}

		{%- endif %}
		{{ page.permalink | safe }}

		{%- if page.extra.link_url -%}
		{%- set lead_url = page.extra.link_url | escape_xml -%}
		{%- set lead_title = page.title | escape_xml -%}
		{%- set lead = '
→ ' ~ lead_title ~ '' -%}
		{{ lead }}
		{%- endif -%}
		{{ page.content }}

	{%- endfor %}
